"""Show saved prompt-only essential-parts replay, without generating predictions."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'reports/part2/parts_prompt_replay_20261029'
SOURCE=ROOT/'reports/part2/ephemeral_rag_pilot_20261029'


def main():
    summary=json.loads((OUT/'summary.json').read_text());protocol=json.loads((OUT/'protocol.json').read_text())
    rows=[json.loads(l) for l in (SOURCE/'results.jsonl').read_text().splitlines()];cases=[]
    for row in rows:
        cases.append(dict(id=row['id'],claim=row['claim'],gold=row['gold'],before=json.loads((SOURCE/'traces'/('%s_ephemeral_full_article_rag.json'%row['id'])).read_text()),
            after=json.loads((OUT/'traces'/('%s.json'%row['id'])).read_text())))
    data=json.dumps(dict(summary=summary,protocol=protocol,cases=cases),ensure_ascii=False).replace('<','\\u003c')
    page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FEVER · Essential-parts prompt replay</title><style>
*{box-sizing:border-box}body{font:14px/1.6 system-ui;margin:0;color:#18364a;background:#f2f7f9}main{max-width:1300px;margin:auto;padding:28px}a{color:#176f77}h1{font-size:35px;letter-spacing:-1px}h2{font-size:20px}.small,small{font-size:11px;color:#607582}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.panel,.metric{background:white;border:1px solid #dbe6ec;border-radius:12px;padding:20px;margin:14px 0;min-width:0}.metric strong{display:block;font-size:31px}.notice{background:#fff2df;border-left:3px solid #d1a352;padding:12px;font-size:12px}.layout{display:grid;grid-template-columns:310px minmax(0,1fr);gap:20px}.case{display:block;text-align:left;width:100%;font:inherit;border:1px solid #c4d6df;border-radius:8px;padding:12px;background:white;margin:8px 0;cursor:pointer}.case.active{background:#e5f4ee;border-color:#167d76}.case strong{display:block;font-size:12px}.labels{display:flex;gap:9px;flex-wrap:wrap}.label{background:#edf3f6;border-radius:7px;padding:12px;font-size:11px;flex:1;min-width:120px}.label b{display:block;font-size:16px}.correct{background:#e4f3ea}.wrong{background:#fff0e3}.part{border-left:3px solid #769dad;padding:0 14px;margin:20px 0}.quote{background:#f1f7f4;padding:10px;font-size:12px}pre{font:11px/1.6 ui-monospace,monospace;background:#142e42;color:#e7f1f7;padding:15px;border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:440px;overflow:auto}summary{font-size:12px;font-weight:650;cursor:pointer}details{border-top:1px solid #dbe6ec;margin:16px 0;padding-top:12px}button,select{font:inherit;cursor:pointer;padding:9px;border:1px solid #bfd1da;background:white;border-radius:7px}.claim{font-size:23px;line-height:1.4}aside{position:sticky;top:15px;align-self:start}select{width:100%;font-size:12px}@media(max-width:850px){main{padding:18px}.layout{grid-template-columns:1fr}aside{position:static}#cases{max-height:230px;overflow:auto}.cards{gap:6px}.metric{padding:12px}.metric strong{font-size:25px}h1{font-size:28px}}
</style></head><body><main><a href="/ephemeral-rag">← Original temporary-RAG pilot</a><p class="small">SAVED DEVELOPMENT REPLAY · SAME TEN CLAIMS AND EXACT EVIDENCE</p><h1>Essential parts. Explicit verdicts.</h1><p>The user-supplied prompt requests part verdicts and an overall label. The application computes a separate label for comparison; disagreement is shown rather than hidden.</p><div id="cards" class="cards"></div><p id="status" class="notice"></p><p class="small">These examples were inspected before the revision. This is development analysis, not a new held-out improvement estimate. No new articles, embeddings or vector databases were created.</p><div class="layout"><aside><h2>Claim traces</h2><select id="filter" aria-label="Filter replay claims"><option value="all">All ten claims</option><option value="fixed">Model label fixed an error</option><option value="regressed">Model label introduced an error</option><option value="invalid">Invalid / incomplete output</option><option value="disagreement">Model vs derived disagreement</option></select><div id="cases"></div></aside><article id="detail"></article></div><section class="panel"><h2>Exact user-approved instruction</h2><pre id="instruction"></pre><div id="limits"></div></section></main><script type="application/json" id="data">PAYLOAD</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let selected=null;
function el(t,text,c){const n=document.createElement(t);if(text!==undefined&&text!==null)n.textContent=text;if(c)n.className=c;return n;}
function details(title,value){const d=el('details'),s=el('summary',title);s.setAttribute('aria-label',title);d.append(s,el('pre',typeof value==='string'?value:JSON.stringify(value,null,2)));return d;}
function list(){const f=$('filter').value,rows=D.cases.filter(r=>f==='all'||f==='fixed'&&r.before.label!==r.gold&&r.after.model_label===r.gold||f==='regressed'&&r.before.label===r.gold&&r.after.model_label!==r.gold||f==='invalid'&&r.after.model_label==='INVALID'||f==='disagreement'&&r.after.consistent===false);$('cases').replaceChildren();for(const r of rows){const b=el('button',undefined,'case'+(r.id===selected?' active':''));b.append(el('small','#'+r.id),el('strong',r.claim),el('small',r.before.label+' → '+r.after.model_label));b.addEventListener('click',()=>show(r));$('cases').append(b);}if(rows.length&&!rows.some(r=>r.id===selected))show(rows[0]);if(!rows.length)$('cases').append(el('p','No matching claims.','small'));}
function show(r){selected=r.id;history.replaceState(null,'','#'+r.id);const root=$('detail');root.replaceChildren();const top=el('section',undefined,'panel');top.append(el('small','#'+r.id),el('h2',r.claim,'claim'));const labels=el('div',undefined,'labels');for(const[name,value]of [['FEVER reference',r.gold],['Previous RAG',r.before.label],['Updated model',r.after.model_label],['Code-derived',r.after.derived_label]]){const box=el('div',undefined,'label '+(value===r.gold?'correct':'wrong'));box.append(el('span',name),el('b',value));labels.append(box);}top.append(labels,el('p','Model / derived agreement: '+r.after.consistent,'small'));if(r.after.error)top.append(el('p',r.after.error,'notice'));root.append(top);
const parts=el('section',undefined,'panel');parts.append(el('h2','Each essential part and its evidence verdict'));if(!r.after.parts)parts.append(el('p','No validated parts: inspect the complete raw output below.','notice'));for(const [i,p] of (r.after.parts||[]).entries()){const item=el('div',undefined,'part');item.append(el('b','Part '+(i+1)+' · '+p.verdict),el('p',p.part),el('p',p.justification,'small'));for(const id of p.evidence_ids){const evidence=r.after.supplied_evidence[id];const q=el('div',undefined,'quote');q.append(el('b',id+' · '+evidence.title),el('p',evidence.text));const a=el('a','Source revision ↗');if(evidence.revision_url.startsWith('https://en.wikipedia.org/'))a.href=evidence.revision_url;q.append(a);item.append(q);}parts.append(item);}parts.append(el('p','Consistency validates the aggregation of reported verdicts, not whether decomposition or factual judgments are correct.','small'));root.append(parts);
const raw=el('section',undefined,'panel');raw.append(el('h2','What Llama actually returned'),el('pre',r.after.raw?.response?.message?.content||r.after.error||'No response'),details('Previous RAG response',r.before.raw?.response?.message?.content||''),details('Updated: full exact prompt',r.after.prompt),details('Updated: full raw request and response',r.after.raw||{}),details('All supplied excerpts (unchanged)',r.after.supplied_evidence),details('Previous: full exact prompt',r.before.prompt));const b=el('button','Download before + after traces ↓');b.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download='parts-replay-'+r.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});raw.append(b);root.append(raw);document.querySelectorAll('.case').forEach(b=>b.classList.toggle('active',b.textContent.startsWith('#'+r.id)));}
for(const[name,count]of [['Previous RAG',D.summary.previous_rag_correct],['Updated model label',D.summary.model_label_correct],['Code-derived label',D.summary.derived_label_correct]]){const c=el('div',undefined,'metric');c.append(el('small',name),el('strong',count+' / 10'));$('cards').append(c);}$('status').textContent='Invalid outputs: '+D.summary.invalid+' · Model/derived disagreements: '+D.summary.inconsistent+' · Generation limit unchanged at '+D.protocol.settings.num_predict+' tokens.';$('instruction').textContent=D.protocol.prompt;for(const s of D.summary.limitations)$('limits').append(el('p',s,'small'));$('filter').addEventListener('change',list);const id=Number(location.hash.slice(1));if(D.cases.some(r=>r.id===id))selected=id;list();show(D.cases.find(r=>r.id===selected)||D.cases[0]);
</script></body></html>'''
    (OUT/'index.html').write_text(page.replace('PAYLOAD',data))
    print('Built',OUT/'index.html')

if __name__=='__main__':main()
